import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import assert from 'node:assert/strict';
const root=path.resolve(import.meta.dirname,'../..');
const bytes=p=>fs.readFileSync(path.join(root,p));
const hash=b=>crypto.createHash('sha256').update(b).digest('hex');
const pin=p=>{const b=bytes(p);return {path:p,size:b.length,sha256:hash(b)};};
const receiptPath='docs/evidence/a-bootstrap-security-local-20261022-154243-00f9034a.json';
const logPath='docs/evidence/a-bootstrap-reference-typed-20261022-154239-164b7bc4.txt';
assert.equal(hash(bytes(receiptPath)),'2b864e55e9327eaedaba35e60315d186a9cf5c766cc9fb6457aebd11a5a66abd');
assert.equal(hash(bytes(logPath)),'b0060845fcd1a1289b2847fd969b1b090294cc750319e941c9e85f53eac76d9c');
const result=JSON.parse(bytes(receiptPath)),log=bytes(logPath).toString('utf8').replaceAll('\r\n','\n');
for(const flag of ['linux_build','frozen_validation_passed','current_inputs_match','cleanup_verified','default_vet'])assert.equal(result[flag],true,flag);
assert.equal(result.dependencies_installed,false);assert.equal(result.remote_contacted,false);
assert.equal(result.files.length,374);assert.equal(new Set(result.files.map(f=>f.path)).size,374);
assert.equal(hash(result.files.map(p=>`${p.path}\0${p.sha256}\0${p.size}`).join('\n')+'\n'),result.source_sha256);
for(const p of [...result.files,...result.validation_inputs])assert.deepEqual(pin(p.path),p,'current selected input differs: '+p.path);
assert.equal(result.frozen_source.matches,true);assert.equal(result.current_source.matches,true);assert.equal(result.current_validation_inputs.matches,true);
assert.doesNotMatch(log,/^FAIL(?:\s|$)|^\s*--- (?:FAIL|SKIP):|^panic:/m);
const packages=[...log.matchAll(/^ok\s+(clawreef\/\S+)\s+([0-9.]+)s$/gm)].map(m=>({package:m[1],seconds:Number(m[2])}));
assert.deepEqual(packages.map(p=>p.package),['clawreef/internal/systembackupsecurity','clawreef/internal/systembackupbootstrapsecurity','clawreef/cmd/system-backup-bootstrap']);
assert.ok(log.includes('CLEANED bootstrap_security=True'));
const vectors=JSON.parse(bytes('contracts/system-backup/v12/a-secret-ref-vectors.json'));
assert.equal(vectors.cases.length,29);
const observedOwner=path.join(root,'.tmp-a-evidence-b5e19b8db11843748192736b6c741405');
assert.equal(fs.existsSync(observedOwner),false);
const report={kind:'a_bootstrap_reference_typed_independent_review.v1',status:'typed_metadata_layer_accepted_no_resource_admission',receipt:pin(receiptPath),log:pin(logPath),source_sha256:result.source_sha256,selected_source_files:374,selected_current_pins_match:true,packages,existing_reference_vectors:29,default_vet:true,linux_command_build:true,cleanup:{raw_receipt_reports_cleaned:true,owner_identifier_in_raw_receipt:false,owner_observed_during_run:observedOwner,observed_owner_independently_absent:true},scope:{metadata_decode_and_pin_correspondence:true,resource_Prepare_Recheck:false,linked_adapter_slots_cleared:0,remaining_linked_owner_slots:27,actual_provider:false,actual_MySQL:false,current_whole_worktree_tested:false,dependencies_installed:false,production_approved:false}};
const output=path.join(root,'docs/evidence/a-bootstrap-reference-typed-accepted-20261022.json');
if(process.argv.includes('--check'))assert.deepEqual(JSON.parse(fs.readFileSync(output,'utf8')),report);
else fs.writeFileSync(output,JSON.stringify(report,null,2)+'\n',{flag:'wx'});
console.log('A_TYPED_REFERENCE_REVIEW packages=3 vectors=29 linux_build=yes selected_pins=374 cleanup=yes actual_admission=no');
